import express from 'express';
import { createStore } from 'zustand/vanilla';
import { verifyTenantToken } from '../auth.js';
import { getOrgSettings } from '../services/organization.js';

const app = express();

// Shared module-scoped Zustand store for SSR organization context
const orgStore = createStore((set) => ({
  orgId: null,
  ssoConfig: null,
  apiKeys: [],
  setOrg: (data) => set(data)
}));

app.get('/ssr/workspace/:orgId/settings', verifyTenantToken, async (req, res) => {
  const { orgId } = req.params;

  // Hydrates global Zustand store with requested organization's private settings
  const settings = await getOrgSettings(orgId);
  if (!settings) {
    return res.status(404).send('Organization not found');
  }

  orgStore.getState().setOrg({
    orgId,
    ssoConfig: settings.samlCertificate,
    apiKeys: settings.decryptedServiceKeys
  });

  const currentOrg = orgStore.getState();
  res.send(`
    <script>window.__WORKSPACE_DATA__ = ${JSON.stringify(currentOrg)};</script>
    <div>Organization ${currentOrg.orgId} Management</div>
  `);
});

